const responsePromise = Promise.withResolvers()

// The response that ends up in the cache is a clone of the fetched one,
// taken before its body is read, so that the cached body can be read
// again later. See the note in processResponse below.
let clonedResponse = null
/** @type {Promise<Uint8Array|undefined>|null} */
let bodyReadPromise = null

// 5.7
fetchControllers.push(fetching({
  request: r,
  processResponse (response) {
    // 1.
    if (response.type === 'error' || response.status === 206 || response.status < 200 || response.status > 299) {
      responsePromise.reject(webidl.errors.exception({
        header: 'Cache.addAll',
        message: 'Received an invalid status code or the request failed.'
      }))

      // Nothing is going to read this body, cancel it so the connection
      // isn't left hanging.
      cancelResponseBody(response)
      return
    } else if (response.headersList.contains('vary')) { // 2.
      // 2.1
      const fieldValues = getFieldValues(response.headersList.get('vary'))

      // 2.2
      for (const fieldValue of fieldValues) {
        // 2.2.1
        if (fieldValue === '*') {
          responsePromise.reject(webidl.errors.exception({
            header: 'Cache.addAll',
            message: 'invalid vary field value'
          }))

          for (const controller of fetchControllers) {
            controller.abort()
          }

          return
        }
      }
    }

    // Not in the spec. undici's fetch doesn't pipe the response body
    // through an identity transform stream (see fetchFinale), so the
    // body is only drained once something reads it. Nothing would here,
    // meaning process response end-of-body — and therefore addAll's
    // promise — would never run.
    // Reading the body now also gives the cached response bytes it can
    // replay, the same way Cache.put does.
    clonedResponse = cloneResponse(response)
    bodyReadPromise = readResponseBody(response)
  },
  processResponseEndOfBody (response) {
    // 1.
    if (response.aborted) {
      responsePromise.reject(new DOMException('aborted', 'AbortError'))
      return
    }

    // 2.
    responsePromise.resolve(bodyReadPromise.then((bytes) => {
      const innerResponse = clonedResponse.internalResponse ?? clonedResponse

      if (innerResponse.body != null) {
        innerResponse.body.source = bytes
      }

      return clonedResponse
    }))
  }
}))

