import { createServer } from 'node:http'
import { setTimeout as sleep } from 'node:timers/promises'
import { caches } from './index.js'

process.on('uncaughtException', (e) => { console.log('UNCAUGHT', e); process.exit(1) })
process.on('unhandledRejection', (e) => { console.log('UNHANDLED', e); process.exit(1) })

const server = createServer((req, res) => {
  if (req.url === '/404') {
    res.writeHead(404)
    res.end('nope'.repeat(10000))
  } else if (req.url === '/vary') {
    res.writeHead(200, { vary: '*' })
    res.end('varies'.repeat(10000))
  } else {
    res.writeHead(200, { 'content-type': 'text/plain' })
    res.end('body for ' + req.url)
  }
}).listen(0)

await new Promise(r => server.once('listening', r))
const base = 'http://localhost:' + server.address().port

const cache = await caches.open('t')

await cache.add(base + '/404').then(() => console.log('BAD'), (e) => console.log('404 rejected:', e.name))
await cache.add(base + '/vary').then(() => console.log('BAD'), (e) => console.log('vary rejected:', e.name))
await sleep(500)
console.log('no uncaught errors')
server.close()

