import { createServer } from 'node:http'
import { caches } from './index.js'

const server = createServer((req, res) => {
  if (req.url === '/404') {
    res.writeHead(404)
    res.end('nope')
  } else if (req.url === '/vary') {
    res.writeHead(200, { vary: '*' })
    res.end('varies')
  } else if (req.url === '/204') {
    res.writeHead(204)
    res.end()
  } else if (req.url === '/big') {
    res.writeHead(200, { 'content-type': 'text/plain' })
    res.end('x'.repeat(1024 * 1024))
  } else {
    res.writeHead(200, { 'content-type': 'text/plain' })
    res.end('body for ' + req.url)
  }
}).listen(0)

await new Promise(r => server.once('listening', r))
const base = 'http://localhost:' + server.address().port

const timer = setTimeout(() => {
  console.log('HANG')
  process.exit(1)
}, 5000)

const cache = await caches.open('t')

// addAll with several urls
await cache.addAll([base + '/a', base + '/b', base + '/big', base + '/204'])
console.log('a:', await (await cache.match(base + '/a')).text())
console.log('b:', await (await cache.match(base + '/b')).text())
console.log('big len:', (await (await cache.match(base + '/big')).text()).length)
console.log('a again:', await (await cache.match(base + '/a')).text())
const r204 = await cache.match(base + '/204')
console.log('204:', r204.status, await r204.text() === '')
console.log('keys:', (await cache.keys()).map(r => new URL(r.url).pathname))

// failing status
await cache.add(base + '/404').then(
  () => console.log('404: UNEXPECTED resolve'),
  (e) => console.log('404 rejected:', e.name)
)

// vary: *
await cache.add(base + '/vary').then(
  () => console.log('vary: UNEXPECTED resolve'),
  (e) => console.log('vary rejected:', e.name)
)

// mixed batch where one fails
await cache.addAll([base + '/c', base + '/404']).then(
  () => console.log('mixed: UNEXPECTED resolve'),
  (e) => console.log('mixed rejected:', e.name)
)
console.log('c not cached:', (await cache.match(base + '/c')) === undefined)

clearTimeout(timer)
server.close()
console.log('done — event loop should now drain')

